function f(t,o){let n=document.getElementById(t);n&&(n.textContent=o)}function i(t){return t.replace(/[^a-zA-Z0-9]/g,"_")}function c(t){if(t<60)return t+"s";let o=Math.floor(t/60),n=t%60;if(o<60)return o+"m "+n+"s";let r=Math.floor(o/60),e=o%60;return r+"h "+e+"m"}function u(t){if(t===0)return"0 B";let o=["B","KB","MB","GB","TB"],n=Math.floor(Math.log(t)/Math.log(1024)),r=t/Math.pow(1024,n);return(n===0?t:r.toFixed(1))+" "+o[n]}export{f as a,i as b,c,u as d};
